#![allow(dead_code)]
#[path="../apps/spindle/src/scroll_view.rs"]mod scroll_view;
include!(env!("SPINDLE_SCROLL_SOURCE"));
#[test]fn page_step_tracks_visible_rows_and_never_overflows(){assert_eq!(scroll_view::page(0,true,30,1),1);assert_eq!(scroll_view::page(0,true,30,11),11);assert_eq!(scroll_view::page(11,false,30,11),0);assert_eq!(scroll_view::page(u32::MAX,true,u32::MAX,11),1013);assert_eq!(scroll_view::page(4,true,30,0),0);assert_eq!(scroll_view::page(0,true,0,11),0);}
#[test]fn ring_wrap_exposes_only_retained_lines_in_chronological_order(){let mut s=Scrollback::new();for n in 0..1100{s.push(n.to_string().as_bytes());}assert_eq!(s.retained(),1024);assert_eq!(s.get_retained(0),b"76");assert_eq!(s.get_retained(1023),b"1099");assert_eq!(s.get_retained(1024),b"");}
#[test]fn saturated_lifetime_counter_does_not_freeze_retained_ring_selection(){let mut s=Scrollback::new();for _ in 0..1024{s.push(b"old");}s.total_lines=u32::MAX-1;s.push(b"new one");s.push(b"new two");s.push(b"new three");assert_eq!(s.total_lines,u32::MAX);assert_eq!(s.get_retained(1023),b"new three");assert_eq!(s.get_retained(1022),b"new two");assert_eq!(s.get_retained(1021),b"new one");}
#[test]fn new_output_preserves_scrolled_selection_and_live_tail_stays_live(){let mut s=Scrollback::new();for line in [b"one" as &[u8],b"two",b"three",b"four"]{s.push(line);}s.scroll_offset=2;let before=s.get_retained(s.retained()-1-s.scroll_offset as usize).to_vec();s.push(b"five");assert_eq!(s.scroll_offset,3);assert_eq!(s.get_retained(s.retained()-1-s.scroll_offset as usize),before);s.scroll_offset=0;s.push(b"six");assert_eq!(s.scroll_offset,0);}
#[test]fn eviction_and_resize_clamp_to_retained_output_instead_of_stale_slots(){assert_eq!(scroll_view::after_push(1023,u32::MAX),1023);assert_eq!(scroll_view::clamp(20,3,11),0);assert_eq!(scroll_view::clamp(20,30,11),19);assert_eq!(scroll_view::index(3,3,0),Some(0));assert_eq!(scroll_view::index(3,u32::MAX,1023),Some(2));}
